INSERT INTO `ha_posts` (`post_author`,`post_date`,`post_date_gmt`,`post_content`,`post_title`,`post_excerpt`,`post_status`,`comment_status`,`ping_status`,`post_name`,`post_modified`,`post_modified_gmt`,`post_parent`,`guid`,`menu_order`,`post_type`,`post_mime_type`,`comment_count`) VALUES (1,NOW(),UTC_TIMESTAMP(),'','بازرسی و نگهداری نوار آبیاری در مزرعه ساروق','','inherit','open','closed','نوار-تیپ-20-سانتی-ساروق-مرکزی-navar-tip-20cm-اتصال-و-کاربرد',NOW(),UTC_TIMESTAMP(),@post_id,'https://navar-abyari.ir/wp-content/uploads/2026/09/navar-city-generated/نوار-تیپ-20-سانتی-ساروق-مرکزی-navar-tip-20cm-اتصال-و-کاربرد.jpg',0,'attachment','image/jpeg',0); SET @media_5=LAST_INSERT_ID(); INSERT INTO `ha_postmeta` (`post_id`,`meta_key`,`meta_value`) VALUES (@media_5,'_wp_attached_file','2026/09/navar-city-generated/نوار-تیپ-20-سانتی-ساروق-مرکزی-navar-tip-20cm-اتصال-و-کاربرد.jpg'),(@media_5,'_wp_attachment_image_alt','بازرسی و نگهداری نوار آبیاری در مزرعه ساروق');
